mapper.update:
update team_settlement
set settlement_status = '지급완료', settled_at = now(), admin_id = #{adminId}
where settlement_id = #{settlementId}
and settlement_status = '정산대기'

mapper.select:
select tm.team_match_id, t.team_id, t.team_name, date_format(tm.match_date,'%Y.%m.%d') as match_date_fmt, elt(dayofweek(tm.match_date),'일','월','화','수','목','금','토') as match_day, date_format(tm.start_time,'%H:%i') as start_time_fmt, tm.match_people, tm.title, tm.sport, tm.region, tm.place_name, tm.status as match_status, tm.participation_fee, tm.fee, ts.settlement_status, date_format(ts.settled_at,'%c/%d') as settled_fmt from team_match tm join team t on (t.team_id = tm.team_id) left join team_settlement ts on (ts.team_match_id = tm.team_match_id) where tm.status = '경기 종료' and ifnull(tm.deleted, 0) = 0 and tm.match_date between #{startDate} and #{endDate} and exists (select 1 from team_user tu where tu.team_id = tm.team_id and tu.user_id = #{userId} and tu.team_role = 'CAPTAIN' and ifnull(tu.withdrawn, 0) = 0) and exists (select 1 from team_match_participant tmp where tmp.team_match_id = tm.team_match_id and tmp.status = '결제완료')
and tm.title like concat('%', #{keyword}, '%')
and ts.settlement_status = #{settlementStatus}
and tm.team_id = #{teamId}
order by tm.match_date desc, tm.start_time desc limit #{row}, 10

		select count(*)
   		from team_match tm join team t on (t.team_id = tm.team_id)
         left join team_settlement ts on (ts.team_match_id = tm.team_match_id)
	    where tm.status = '경기 종료' and ifnull(tm.deleted, 0) = 0 and tm.match_date between #{startDate} and #{endDate}
   			  and exists (select 1 from team_user tu
                  		  where tu.team_id = tm.team_id and tu.user_id = #{userId}
                    		    and tu.team_role = 'CAPTAIN' and ifnull(tu.withdrawn, 0) = 0)
        	  and exists (select 1 from team_match_participant tmp
           				  where tmp.team_match_id = tm.team_match_id and tmp.status = '결제완료')                    		    

      	and tm.title like concat('%', #{keyword}, '%')


      	and ts.settlement_status = #{settlementStatus}


      	and tm.team_id = #{teamId}

	    select count(*) as all_cnt,
 	          count(case when ts.settlement_status='정산대기' then 1 end) as wait_cnt,
 	          count(case when ts.settlement_status='지급완료' then 1 end) as done_cnt
	    from team_match tm join team t on (t.team_id = tm.team_id)
        				   left join team_settlement ts on (ts.team_match_id = tm.team_match_id)
 		where tm.status = '경기 종료' and ifnull(tm.deleted, 0) = 0 and tm.match_date between #{startDate} and #{endDate}
     		  and exists (select 1 from team_user tu
                  		  where tu.team_id = tm.team_id and tu.user_id = #{userId}
                    			and tu.team_role = 'CAPTAIN' and ifnull(tu.withdrawn, 0) = 0)
        	  and exists (select 1 from team_match_participant tmp
           				  where tmp.team_match_id = tm.team_match_id and tmp.status = '결제완료')                    			

      	and tm.title like concat('%', #{keyword}, '%')


      	and tm.team_id = #{teamId}
